INSERT INTO item VALUES (1298,'Amulet of Natural Armor +2','Wondrous',NULL,'No','Faint transmutation','5','8,000 gp',NULL,'Craft Wondrous Item, barkskin, creator\'s caster level must be at least three times the amulet\'s bonus',NULL,NULL,'\n      <div topic=\"Amulet of Natural Armor\" level=\"8\"><p><b>Amulet of Natural Armor:</b> This amulet, usually crafted from bone or beast scales, toughens the wearer\'s body and flesh, giving him an enhancement bonus to his natural armor bonus of from +1 to +5, depending on the kind of amulet.</p><p>Faint transmutation; CL 5th; Craft Wondrous Item, <i>barkskin</i>,  creator\'s caster level must be at least three times the amulet\'s bonus; Price 2,000 gp (+1), 8,000 gp (+2), 18,000 gp (+3), 32,000 gp (+4), or 50,000 gp (+5).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1299,'Amulet of Natural Armor +3','Wondrous',NULL,'No','Faint transmutation','5','18,000 gp',NULL,'Craft Wondrous Item, barkskin, creator\'s caster level must be at least three times the amulet\'s bonus',NULL,NULL,'\n      <div topic=\"Amulet of Natural Armor\" level=\"8\"><p><b>Amulet of Natural Armor:</b> This amulet, usually crafted from bone or beast scales, toughens the wearer\'s body and flesh, giving him an enhancement bonus to his natural armor bonus of from +1 to +5, depending on the kind of amulet.</p><p>Faint transmutation; CL 5th; Craft Wondrous Item, <i>barkskin</i>,  creator\'s caster level must be at least three times the amulet\'s bonus; Price 2,000 gp (+1), 8,000 gp (+2), 18,000 gp (+3), 32,000 gp (+4), or 50,000 gp (+5).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1300,'Amulet of Natural Armor +4','Wondrous',NULL,'No','Faint transmutation','5','32,000 gp',NULL,'Craft Wondrous Item, barkskin, creator\'s caster level must be at least three times the amulet\'s bonus',NULL,NULL,'\n      <div topic=\"Amulet of Natural Armor\" level=\"8\"><p><b>Amulet of Natural Armor:</b> This amulet, usually crafted from bone or beast scales, toughens the wearer\'s body and flesh, giving him an enhancement bonus to his natural armor bonus of from +1 to +5, depending on the kind of amulet.</p><p>Faint transmutation; CL 5th; Craft Wondrous Item, <i>barkskin</i>,  creator\'s caster level must be at least three times the amulet\'s bonus; Price 2,000 gp (+1), 8,000 gp (+2), 18,000 gp (+3), 32,000 gp (+4), or 50,000 gp (+5).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1301,'Amulet of Natural Armor +5','Wondrous',NULL,'No','Faint transmutation','5','or 50,000 gp',NULL,'Craft Wondrous Item, barkskin, creator\'s caster level must be at least three times the amulet\'s bonus',NULL,NULL,'\n      <div topic=\"Amulet of Natural Armor\" level=\"8\"><p><b>Amulet of Natural Armor:</b> This amulet, usually crafted from bone or beast scales, toughens the wearer\'s body and flesh, giving him an enhancement bonus to his natural armor bonus of from +1 to +5, depending on the kind of amulet.</p><p>Faint transmutation; CL 5th; Craft Wondrous Item, <i>barkskin</i>,  creator\'s caster level must be at least three times the amulet\'s bonus; Price 2,000 gp (+1), 8,000 gp (+2), 18,000 gp (+3), 32,000 gp (+4), or 50,000 gp (+5).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1302,'Amulet of the Planes','Wondrous',NULL,'No','Strong conjuration','15','120,000 gp',NULL,'Craft Wondrous Item, plane shift',NULL,NULL,'\n      <div topic=\"Amulet of the Planes\" level=\"8\"><p><b>Amulet of the Planes:</b> This device usually appears to be a black circular amulet, although any character looking closely at it sees a dark, moving swirl of color. The amulet allows its wearer to utilize <i>plane shift</i>. However, this is a difficult item to master. The user must make a DC 15 Intelligence check in order to get the amulet to take her to the plane (and the specific location on that plane) that she wants. If she fails, the amulet transports her and all those traveling with her to a random location on that plane (01-60 on d%) or to a random plane (61-100).</p><p>Strong conjuration; CL 15th; Craft Wondrous Item, <i>plane shift</i>; Price 120,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1303,'Amulet of Proof Against Detection and Location','Wondrous',NULL,'No','Moderate abjuration','8','35,000 gp',NULL,'Craft Wondrous Item, nondetection',NULL,NULL,'\n      <div topic=\"Amulet of Proof Against Detection and Location\" level=\"8\"><p><b>Amulet of Proof against Detection and Location:</b> This silver amulet protects the wearer from scrying and magical location just as a <i>nondetection</i> spell does. If a divination spell is attempted against the wearer, the caster of the divination must succeed on a caster level check (1d20 + caster level) against a DC of 19 (as if the caster had cast <i>nondetection</i> on herself ).</p><p>Moderate abjuration; CL 8th; Craft Wondrous Item, <i>nondetection</i>; Price 35,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1304,'Apparatus of the Crab','Wondrous',NULL,'No','Strong evocation and transmutation','19','90,000 gp',NULL,'Craft Wondrous Item, animate objects, continual flame, creator must have 8 ranks in the Knowledge (architecture and engineering) skill',NULL,'500 lb','\n      <div topic=\"Apparatus of the Crab\" level=\"8\"><p><b>Apparatus of the Crab:</b> This item appears to be a large, sealed iron barrel, but it has a secret catch (Search DC 20 to locate) that opens a hatch in one end. Anyone who crawls inside finds ten (unlabeled) levers: The device has the following characteristics: hp 200; hardness 15; Spd 20 ft., swim 20 ft.; AC 20 (-1 size, +11 natural); Atk +12 melee (2d8, 2 pincers).</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Lever (1d10)</b><br/></td> <td><b>Lever Function</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>Extend/retract legs and tail<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2<br/></td>\n<td>Uncover/cover forward porthole<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>3<br/></td>\n<td>Uncover/cover side portholes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4<br/></td>\n<td>Extend/retract pincers and feelers<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5<br/></td>\n<td>Snap pincers<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6<br/></td>\n<td>Move forward/backward<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>7<br/></td>\n<td>Turn left/right<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8<br/></td>\n<td>Open \'eyes\' with <i>continual flame</i> inside/close \'eyes\'<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>9<br/></td>\n<td>Rise/sink in water<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10<br/></td>\n<td>Open/close hatch<br/></td>\n\n</tr>\n</table><p/><p>Operating a lever is a full-round action, and no lever may be operated more than once per round. However, since two Medium characters can fit inside, the apparatus can move and attack in the same round. The device can function in water up to 900 feet deep. It holds enough air for a crew of two to survive 1d4+1 hours (twice as long for a single occupant). When activated, the apparatus looks something like a giant lobster.</p><p>Strong evocation and transmutation; CL 19th; Craft Wondrous Item, <i>animate objects</i>, <i>continual flame</i>, creator must have 8 ranks in the Knowledge (architecture and engineering) skill; Price 90,000 gp;<i>Weight</i> 500 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1305,'Bag of Holding','Wondrous',NULL,'No','Moderate conjuration','9',NULL,NULL,'Craft Wondrous Item, secret chest',NULL,NULL,'\n      <div topic=\"Bag of Holding\" level=\"8\"><p><b>Bag of Holding:</b> This appears to be a common cloth sack about 2 feet by 4 feet in size. The <i>bag of holding</i> opens into a nondimensional space: Its inside is larger than its outside dimensions. Regardless of what is put into the bag, it weighs a fixed amount. This weight, and the limits in weight and volume of the bag\'s contents, depend on the bag\'s type, as shown on the table below.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Bag</b><br/></td> <td><b>Bag Weight</b><br/></td>\n<td><b>Contents Weight Limit</b><br/></td>\n<td><b>Contents Volume Limit</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Type I<br/></td>\n<td>15 lb.<br/></td>\n<td>250 lb.<br/></td>\n<td>30 cu. ft.<br/></td>\n<td>2,500 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Type II<br/></td>\n<td>25 lb.<br/></td>\n<td>500 lb.<br/></td>\n<td>70 cu. ft.<br/></td>\n<td>5,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Type III<br/></td>\n<td>35 lb.<br/></td>\n<td>1,000 lb.<br/></td>\n<td>150 cu. ft.<br/></td>\n<td>7,400 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Type IV<br/></td>\n<td>60 lb.<br/></td>\n<td>1,500 lb.<br/></td>\n<td>250 cu. ft.<br/></td>\n<td>10,000 gp<br/></td>\n\n</tr>\n</table><p>If the bag is overloaded, or if sharp objects pierce it (from inside or outside), the bag ruptures and is ruined. All contents are lost forever. If a <i>bag of holding</i> is turned inside out, its contents spill out, unharmed, but the bag must be put right before it can be used again. If living creatures are placed within the bag, they can survive for up to 10 minutes, after which time they suffocate. Retrieving a specific item from a <i>bag of holding</i> is a move action-unless the bag contains more than an ordinary backpack would hold, in which case retrieving a specific item is a full-round action.</p><p>If a <i>bag of holding</i> is placed within a <i>Portable hole</i> a rift to the Astral Plane is torn in the space: Bag and hole alike are sucked into the void and forever lost. If a <i>portable hole</i> is placed within a <i>bag of holding</i>,  it opens a gate to the Astral Plane: The hole, the bag, and any creatures within a 10-foot radius are drawn there, destroying the <i>portable hole</i> and <i>bag of holding</i> in the process.</p><p>Moderate conjuration; CL 9th; Craft Wondrous Item, <i>secret chest</i>.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1306,'Bag of Tricks, Gray','Wondrous',NULL,'No','Faint or moderate conjuration','3','900 gp',NULL,'Craft Wondrous Item, summon nature\'s ally II (gray), summon nature\'s ally III (rust), or summon nature\'s ally V (tan)',NULL,NULL,'\n      <div topic=\"Bag of Tricks\" level=\"8\"><p><b>Bag of Tricks:</b> This small sack appears normal and empty. However, anyone reaching into the bag feels a small, fuzzy ball. If the ball is removed and tossed up to 20 feet away, it turns into an animal. The animal serves the character who drew it from the bag for 10 minutes (or until slain or ordered back into the bag), at which point it disappears. It can follow any of the commands described in the Handle Animal skill. Each of the three kinds of a <i>bag of tricks</i> produces a different set of animals. Use the following tables to determine what animals can be drawn out of each.</p><p>The heavy warhorse appears with harness and tack and accepts the character who drew it from the bag as a rider.</p><p>Animals produced are always random, and only one may exist at a time. Up to ten animals can be drawn from the bag each week.</p><p>Faint or moderate conjuration; CL 3rd (gray), 5th (rust), 9th (tan); Craft Wondrous Item, <i>summon nature\'s ally II</i> (gray), <i>summon nature\'s ally III</i> (rust), or <i>summon nature\'s ally</i> V (tan); Price 900 gp (gray), 3,000 gp (rust), 6,300 gp (tan).</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"4\">\n<td> <b><i>--- Gray --</i></b><br/></td>\n<td><b><i>---- Rust ----</i></b><br/></td>\n<td colspan=\"4\" align=\"center\"><b><i>---- Tan ----</i></b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>d%</b><br/></td>\n<td><b>Animal</b><br/></td>\n<td><b>d%</b><br/></td>\n<td><b>Animal</b><br/></td>\n<td><b>d%</b><br/></td>\n<td><b>Animal</b><br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>01-30<br/></td>\n<td>Bat<br/></td>\n<td>01-30<br/></td>\n<td>Wolverine<br/></td>\n<td>01-30<br/></td>\n<td>Brown bear<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>31-60<br/></td>\n<td>Rat<br/></td>\n<td>31-60<br/></td>\n<td>Wolf<br/></td>\n<td>31-60<br/></td>\n<td>Lion<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>61-75<br/></td>\n<td>Cat<br/></td>\n<td>61-85<br/></td>\n<td>Boar<br/></td>\n<td>61-80<br/></td>\n<td>Heavy warhorse<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>76-90<br/></td>\n<td>Weasel<br/></td>\n<td>86-100<br/></td>\n<td>Black bear<br/></td>\n<td>81-90<br/></td>\n<td>Tiger<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>91-100<br/></td>\n<td>Badger<br/></td>\n<td/>\n<td/>\n<td>91-100<br/></td>\n<td>Rhinoceros<br/></td>\n\n</tr>\n</table>\n</div>\n    ','SRD 3.5 MagicItemsV');
