INSERT INTO item VALUES (1333,'Bracers of Armor +6','Wondrous',NULL,'No','Moderate conjuration','7','36,000 gp',NULL,'Craft Wondrous Item, mage armor, creator\'s caster level must be at least two times that of the bonus placed in the bracers',NULL,'1 lb','\n      <div topic=\"Bracers of Armor\" level=\"8\"><p><b>Bracers of Armor:</b> These items appear to be wrist or arm guards. They surround the wearer with an invisible but tangible field of force, granting him an armor bonus of +1 to +8, just as though he were wearing armor. Both bracers must be worn for the magic to be effective.</p><p>Moderate conjuration; CL 7th; Craft Wondrous Item, <i>mage armor</i>, creator\'s caster level must be at least two times that of the bonus placed in the bracers; Price 1,000 gp (+1), 4,000 gp (+2), 9,000 gp (+3), 16,000 gp (+4), 25,000 gp (+5), 36,000 gp (+6), 49,000 gp (+7), 64,000 gp (+8); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1334,'Bracers of Armor +7','Wondrous',NULL,'No','Moderate conjuration','7','49,000 gp',NULL,'Craft Wondrous Item, mage armor, creator\'s caster level must be at least two times that of the bonus placed in the bracers',NULL,'1 lb','\n      <div topic=\"Bracers of Armor\" level=\"8\"><p><b>Bracers of Armor:</b> These items appear to be wrist or arm guards. They surround the wearer with an invisible but tangible field of force, granting him an armor bonus of +1 to +8, just as though he were wearing armor. Both bracers must be worn for the magic to be effective.</p><p>Moderate conjuration; CL 7th; Craft Wondrous Item, <i>mage armor</i>, creator\'s caster level must be at least two times that of the bonus placed in the bracers; Price 1,000 gp (+1), 4,000 gp (+2), 9,000 gp (+3), 16,000 gp (+4), 25,000 gp (+5), 36,000 gp (+6), 49,000 gp (+7), 64,000 gp (+8); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1335,'Bracers of Armor +8','Wondrous',NULL,'No','Moderate conjuration','7','64,000 gp',NULL,'Craft Wondrous Item, mage armor, creator\'s caster level must be at least two times that of the bonus placed in the bracers',NULL,'1 lb','\n      <div topic=\"Bracers of Armor\" level=\"8\"><p><b>Bracers of Armor:</b> These items appear to be wrist or arm guards. They surround the wearer with an invisible but tangible field of force, granting him an armor bonus of +1 to +8, just as though he were wearing armor. Both bracers must be worn for the magic to be effective.</p><p>Moderate conjuration; CL 7th; Craft Wondrous Item, <i>mage armor</i>, creator\'s caster level must be at least two times that of the bonus placed in the bracers; Price 1,000 gp (+1), 4,000 gp (+2), 9,000 gp (+3), 16,000 gp (+4), 25,000 gp (+5), 36,000 gp (+6), 49,000 gp (+7), 64,000 gp (+8); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1336,'Brazier of Commanding Fire Elementals','Wondrous',NULL,'No','Strong conjuration','13','100,000 gp',NULL,'Craft Wondrous Item, summon monster VI, summon monster VII',NULL,'5 lb','\n      <div topic=\"Brazier of Commanding Fire Elementals\" level=\"8\"><p><b>Brazier of Commanding Fire Elementals:</b> This device appears to be a normal container for holding burning coals. When a fire is lit in the brazier and the proper summoning words are spoken, a Large fire elemental appears. The summoning words require 1 full round to speak. In all ways the brazier functions as the <i>summon monster VI</i> spell. If brimstone is added, the elemental is Huge instead of Large, and the brazier works as a <i>summon monster</i> VII spell. Only one elemental can be summoned at a time. A new elemental requires a new fire, which cannot be lit until after the first elemental disappears (is dispelled, dismissed, or slain).</p><p>Strong conjuration; CL 13th; Craft Wondrous Item, <i>summon monster VI</i>,  <i>summon monster VII</i>; Price 100,000 gp; Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1337,'Brooch of Shielding','Wondrous',NULL,'No','Faint abjuration','1','1,500 gp',NULL,'Craft Wondrous Item, shield',NULL,NULL,'\n      <div topic=\"Brooch of Shielding\" level=\"8\"><p><b>Brooch of Shielding:</b> This appears to be a piece of silver or gold jewelry used to fasten a cloak or cape. In addition to this mundane task, it can absorb <i>magic missiles</i> of the sort generated by spell or spell-like ability. A brooch can absorb up to 101 points of damage from <i>magic missiles</i> before it melts and becomes useless.</p><p>Faint abjuration; CL 1st; Craft Wondrous Item, <i>shield</i>; Price 1,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1338,'Broom of Flying','Wondrous',NULL,'No','Moderate transmutation','9','17,000 gp',NULL,'Craft Wondrous Item, overland flight, permanency',NULL,'3 lb','\n      <div topic=\"Broom of Flying\" level=\"8\"><p><b>Broom of Flying:</b> This broom is able to fly through the air as if affected by a<i>n overland flight</i> spell (average maneuverability) for up to 9 hours per day (split up as its owner desires). The broom can carry 200 pounds and fly at a speed of 40 feet, or up to 400 pounds at a speed at 30 feet. In addition, the broom can travel alone to any destination named by the owner as long as she has a good idea of the location and layout of that destination. It comes to its owner from as far away as 300 yards when she speaks the command word. The <i>broom of flying</i> has a speed of 40 feet when it has no rider.</p><p>Moderate transmutation; CL 9th; Craft Wondrous Item, <i>overland flight</i>,  <i>permanency</i>; Price 17,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1339,'Candle of Invocation','Wondrous',NULL,'No','Strong conjuration','17','8,400 gp',NULL,'Craft Wondrous Item, gate, creator must be same alignment as candle created',NULL,'1/2 lb','\n      <div topic=\"Candle of Invocation\" level=\"8\"><p><b>Candle of Invocation:</b> Each of these special tapers is dedicated to one of the nine alignments. Simply burning the candle generates a favorable aura for the individual so doing if the candle\'s alignment matches that of the character. Characters of the same alignment as the burning candle add a +2 morale bonus on attack rolls, saving throws, and skill checks while within 30 feet of the flame.</p><p>A cleric whose alignment matches the candle\'s operates as if two levels higher for purposes of determining spells per day if he burns the candle during or just prior to his spell preparation time. He can even cast spells normally unavailable to him, as if he were of that higher level, but only so long as the candle continues to burn. Except in special cases (see below), a candle burns for 4 hours.</p><p>In addition, burning a candle also allows the owner to cast a <i>gate</i> spell, the respondent being of the same alignment as the candle, but the taper is immediately consumed in the process. It is possible to extinguish the candle simply by blowing it out, so users often place it in a lantern to protect it from drafts and the like. Doing this doesn\'t interfere with its magical properties.</p><p>Strong conjuration; CL 17th; Craft Wondrous Item, <i>gate</i>,  creator must be same alignment as candle created; Price 8,400 gp; Weight 1/2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1340,'Candle of Truth','Wondrous',NULL,'No','Faint enchantment','3','2,500 gp',NULL,'Craft Wondrous Item, zone of truth',NULL,'1/2 lb','\n      <div topic=\"Candle of Truth\" level=\"8\"><p><b>Candle of Truth:</b> This white tallow candle, when burned, calls into place a <i>zone of truth</i> spell (Will DC 13 negates) in a 5-foot radius centered on the candle. The zone lasts for 1 hour, as the candle burns. If the candle is snuffed before that time, the effect is canceled and the candle ruined.</p><p>Faint enchantment; CL 3rd; Craft Wondrous Item, <i>zone of truth</i>; Price 2,500 gp; Weight 1/2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1341,'Cape of the Mountebank','Wondrous',NULL,'No','Moderate conjuration','9','10,080 gp',NULL,'Craft Wondrous Item, dimension door',NULL,'1 lb','\n      <div topic=\"Cape of the Mountebank\" level=\"8\"><p><b>Cape of the Mountebank:</b> On command, this bright red and gold cape allows the wearer to use the magic of the <i>dimension door</i> spell once per day. When he disappears, he leaves behind a cloud of smoke, appearing in a similar fashion at his destination.</p><p>Moderate conjuration; CL 9th; Craft Wondrous Item, <i>dimension door</i>; Price 10,080 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1342,'Carpet of Flying','Wondrous',NULL,'No','Moderate transmutation','10',NULL,NULL,'Craft Wondrous Item, overland flight, permanency',NULL,NULL,'\n      <div topic=\"Carpet of Flying\" level=\"8\"><p><b>Carpet of Flying:</b> This rug is able to fly through the air as if affected by an <i>overland flight</i> spell of unlimited duration. The size, carrying capacity, and speed of the different <i>carpets of flying</i> are shown on the table below. Beautifully and intricately made, each carpet has its own command word to activate it-if the device is within voice range, the command word activates it, whether the speaker is on the rug or not. The carpet is then controlled by spoken directions.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Size</b><br/></td> <td><b>Capacity</b><br/></td>\n<td><b>Speed</b><br/></td>\n<td><b>Weight</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>5 ft. by 5 ft.<br/></td>\n<td>200 lb.<br/></td>\n<td>40 ft.<br/></td>\n<td>8 lb.<br/></td>\n<td>20,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>5 ft. by 10 ft.<br/></td>\n<td>400 lb.<br/></td>\n<td>40 ft.<br/></td>\n<td>15 lb.<br/></td>\n<td>35,000 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>10 ft. by 10 ft.<br/></td>\n<td>800 lb.<br/></td>\n<td>40 ft.<br/></td>\n<td>10 lb.<br/></td>\n<td>60,000 gp<br/></td>\n\n</tr>\n</table><p>A <i>carpet of flying</i> can carry up to double its capacity, but doing so reduces its speed to 30 feet. It has average maneuverability, but a <i>carpet of flying</i> can still hover.</p><p>Moderate transmutation; CL 10th; Craft Wondrous Item, <i>overland flight</i>, <i>permanency</i>.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1343,'Censer of Controlling Air Elementals','Wondrous',NULL,'No','Strong conjuration','17','100,000 gp',NULL,'Craft Wondrous Item, summon monster VI, summon monster IX',NULL,'1 lb','\n      <div topic=\"Censer of Controlling Air Elementals\" level=\"8\"><p><b>Censer of Controlling Air Elementals:</b> This 6-inch-wide, 1-inch-high perforated golden vessel resembles a thurible found in a place of worship. If it is filled with incense and lit, summoning words spoken over it summon forth a Large air elemental. The summoning words require 1 full round to speak. In all ways the censer functions as the <i>summon monster VI</i> spell. If <i>incense of meditation</i> is burned within the censer, the air elemental is an elder air elemental instead (as if <i>summon monster IX</i> had just been cast). Only one elemental can be summoned at a time. A new elemental requires a new piece of incense, which cannot be lit until after the first elemental disappears (is dispelled, dismissed, or slain).</p><p>Strong conjuration; CL 17th; Craft Wondrous Item, <i>summon monster VI</i>,  <i>summon monster IX</i>; Price 100,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1344,'Chaos Diamond','Wondrous',NULL,'No','Strong varied','19','160,000 gp',NULL,'Craft Wondrous Item, Cloak of chaos, magic circle against law, random action, word of chaos, creator must be chaotic',NULL,'1 lb','\n      <div topic=\"Chaos Diamond\" level=\"8\"><p><b>Chaos Diamond:</b> This lustrous gemstone is uncut and about the size of a human fist. The gem grants its possessor the following powers:</p><ul>\n <li> <i>Confusion</i>,  <i>lesser</i></li>\n <li> <i>Magic circle against law</i></li>\n <li> <i>Word of chaos</i></li>\n <li> <i>Cloak of chaos</i></li>\n</ul><p>Each power is usable 1d4 times per day. This is rolled for each power individually and the character does not A nonchaotic character who possesses a <i>chaos diamond</i> gains one negative level. Although this level never results in actual level loss, it remains as long as the diamond is in the character\'s possession and cannot be overcome in any way (including <i>restoration</i> spells).</p><p>Strong varied; CL 19th; Craft Wondrous Item, <i>Cloak of chaos</i>,  <i>magic circle against law</i>,  <i>random action</i>,  <i>word of chaos</i>,  creator must be chaotic; Price 160,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1345,'Chime of Interruption','Wondrous',NULL,'No','Moderate evocation','7','16,800 gp',NULL,'Craft Wondrous Item, shout',NULL,'1 lb','\n      <div topic=\"Chime of Interruption\" level=\"8\"><p><b>Chime of Interruption:</b> This instrument can be struck once every 10 minutes, and its resonant tone lasts for 3 full minutes.</p><p>While the chime is resonating, no spell requiring a verbal component can be cast within a 30-foot radius of it unless the caster can make a Concentration check (DC 15 + the spell\'s level).</p><p>Moderate evocation; CL 7th; Craft Wondrous Item, <i>shout</i>; Price 16,800 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1346,'Chime of Opening','Wondrous',NULL,'No','Moderate transmutation','11','3,000 gp',NULL,'Craft Wondrous Item, knock',NULL,'1 lb','\n      <div topic=\"Chime of Opening\" level=\"8\"><p><b>Chime of Opening:</b> A <i>chime of opening</i> is a hollow mithral tube about 1 foot long. When struck, it sends forth magical vibrations that cause locks, lids, doors, valves, and portals to open. The device functions against normal bars, shackles, chains, bolts, and so on. A <i>chime of opening</i> also automatically dispels a <i>hold portal</i> spell or even an <i>arcane lock</i> cast by a wizard of lower than 15th level.</p><p>The chime must be pointed at the item or gate to be loosed or opened (which must be visible and known to the user). The chime is then struck, a clear tone rings forth, and in 1 round the target lock is unlocked, the shackle is loosed, the secret door is opened, or the lid of the chest is lifted. Each sounding only opens one form of locking, so if a chest is chained, padlocked, locked, and <i>arcane locked</i>,  it takes four uses of a <i>chime of opening</i> to get it open. A <i>silence</i> spell negates the power of the device. A brand-new chime can be used a total of ten times before it cracks and becomes useless.</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>knock</i>; Price 3,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1347,'Circlet of Blasting, Minor','Wondrous',NULL,'No','Faint evocation','6','6,480 gp',NULL,'Craft Wondrous Item, searing light',NULL,NULL,'\n      <div topic=\"Circlet of Blasting, Minor\" level=\"8\"><p><b>Circlet of Blasting, Minor:</b> On command, this simple golden headband projects a blast of <i>searing light</i> (3d8 points of damage) once per day.</p><p>Faint evocation; CL 6th; Craft Wondrous Item, <i>searing light</i>; Price 6,480 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1348,'Circlet of Blasting, Major','Wondrous',NULL,'No','Strong evocation','17','23,760 gp',NULL,'Craft Wondrous Item, Maximize Spell, searing light',NULL,NULL,'\n      <div topic=\"Circlet of Blasting, Major\" level=\"8\"><p><b>Circlet of Blasting, Major:</b> On command, this elaborate golden headband projects a blast of <i>searing light</i> (5d8 maximized for 40 points of damage) once per day.</p><p>Strong evocation; CL 17th; Craft Wondrous Item, Maximize Spell, <i>searing light</i>; Price 23,760 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1349,'Circlet of Persuasion','Wondrous',NULL,'No','Faint transmutation','5','4,500 gp',NULL,'Craft Wondrous Item, eagle\'s splendor',NULL,NULL,'\n      <div topic=\"Circlet of Persuasion\" level=\"8\"><p><b>Circlet of Persuasion:</b> This silver headband grants a +3 competence bonus on the wearer\'s Charisma-based checks.</p><p>Faint transmutation; CL 5th; Craft Wondrous Item, <i>eagle\'s splendor</i>; Price 4,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1350,'Cloak of Arachnida','Wondrous',NULL,'No','Faint conjuration and transmutation','6','14,000 gp',NULL,'Craft Wondrous Item, spider climb, web',NULL,'1 lb','\n      <div topic=\"Cloak of Arachnida\" level=\"8\"><p><b>Cloak of Arachnida:</b> This black garment, embroidered with a weblike pattern in silk, gives the wearer the ability to climb as if a <i>spider climb</i> spell had been placed upon her. In addition, the cloak grants her immunity to entrapment by <i>web</i> spells or webs of any sort-she can actually move in webs at half her normal speed. Once per day, the wearer of this cloak can cast <i>web</i>. She also gains a +2 luck bonus on all Fortitude saves against poison from spiders.</p><p>Faint conjuration and transmutation; CL 6th; Craft Wondrous Item, <i>spider climb</i>,  <i>web</i>; Price 14,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1351,'Cloak of the Bat','Wondrous',NULL,'No','Moderate transmutation','7','26,000 gp',NULL,'Craft Wondrous Item, fly, polymorph',NULL,'1 lb','\n      <div topic=\"Cloak of the Bat\" level=\"8\"><p><b>Cloak of the Bat:</b> Fashioned of dark brown or black cloth, this cloak bestows a +5 competence bonus on Hide checks. The wearer is also able to hang upside down from the ceiling, like a bat.</p><p>By holding the edges of the garment, the wearer is able to <i>fly</i> as per the spell. If he desires, the wearer can actually polymorph himself into an ordinary bat and fly accordingly. (All possessions worn or carried are part of the transformation.) Flying, either with the cloak or in bat form, can be accomplished only in darkness (either under the night sky or in a lightless or near-lightless environment underground). Either of the flying powers is usable for up to 7 minutes at a time, but after a flight of any duration the cloak cannot bestow any flying power for a like period of time.</p><p>Moderate transmutation; CL 7th; Craft Wondrous Item, <i>fly</i>,  <i>polymorph</i>; Price 26,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1352,'Cloak of Charisma +2','Wondrous',NULL,'No','Moderate transmutation','8','4,000 gp',NULL,'Craft Wondrous Item, eagle\'s splendor',NULL,'2 lb','\n      <div topic=\"Cloak of Charisma\" level=\"8\"><p><b>Cloak of Charisma:</b> This lightweight and fashionable cloak has a highly decorative silver trim. When in a character\'s possession, it adds a +2, +4, or +6 enhancement bonus to her Charisma score.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>eagle\'s splendor</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6); Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1353,'Cloak of Charisma +4','Wondrous',NULL,'No','Moderate transmutation','8','16,000 gp',NULL,'Craft Wondrous Item, eagle\'s splendor',NULL,'2 lb','\n      <div topic=\"Cloak of Charisma\" level=\"8\"><p><b>Cloak of Charisma:</b> This lightweight and fashionable cloak has a highly decorative silver trim. When in a character\'s possession, it adds a +2, +4, or +6 enhancement bonus to her Charisma score.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>eagle\'s splendor</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6); Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1354,'Cloak of Charisma +6','Wondrous',NULL,'No','Moderate transmutation','8','36,000 gp',NULL,'Craft Wondrous Item, eagle\'s splendor',NULL,'2 lb','\n      <div topic=\"Cloak of Charisma\" level=\"8\"><p><b>Cloak of Charisma:</b> This lightweight and fashionable cloak has a highly decorative silver trim. When in a character\'s possession, it adds a +2, +4, or +6 enhancement bonus to her Charisma score.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>eagle\'s splendor</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6); Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1355,'Cloak of Displacement, Minor','Wondrous',NULL,'No','Faint illusion','3','24,000 gp',NULL,'Craft Wondrous Item, displacement',NULL,'1 lb','\n      <div topic=\"Cloak of Displacement, Minor\" level=\"8\"><p><b>Cloak of Displacement, Minor:</b> This item appears to be a normal cloak, but when worn by a character its magical properties distort and warp light waves. This displacement works similar to the <i>displacement</i> spell except that it only grants a 20% miss chance on attacks against the wearer. It functions continually.</p><p>Faint illusion; CL 3rd; Craft Wondrous Item, <i>displacement</i>; Price 24,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1356,'Cloak of Displacement, Major','Wondrous',NULL,'No','Moderate illusion','7','50,000 gp',NULL,'Craft Wondrous Item, Extend Spell, displacement',NULL,'1 lb','\n      <div topic=\"Cloak of Displacement, Major\" level=\"8\"><p><b>Cloak of Displacement, Major:</b> This item appears to be a normal cloak, but on command its magical properties distort and warp light waves. This displacement works just like the <i>displacement</i> spell and lasts for a total of 15 rounds per day, which the wearer can divide up as she sees fit.</p><p>Moderate illusion; CL 7th; Craft Wondrous Item, Extend Spell, <i>displacement</i>; Price 50,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1357,'Cloak of Elvenkind','Wondrous',NULL,'No','Faint illusion','3','2,500 gp',NULL,'Craft Wondrous Item, invisibility, creator must be an elf',NULL,'1 lb','\n      <div topic=\"Cloak of Elvenkind\" level=\"8\"><p><b>Cloak of Elvenkind:</b> This cloak of neutral gray cloth is indistinguishable from an ordinary cloak of the same color. However, when worn with the hood drawn up around the head, it gives the wearer a +5 competence bonus on Hide checks.</p><p>Faint illusion; CL 3rd; Craft Wondrous Item, <i>invisibility</i>,  creator must be an elf; Price 2,500 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1358,'Cloak of Etherealness','Wondrous',NULL,'No','Strong transmutation','15','55,000 gp',NULL,'Craft Wondrous Item, ethereal jaunt',NULL,'1 lb','\n      <div topic=\"Cloak of Etherealness\" level=\"8\"><p><b>Cloak of Etherealness:</b> This silvery-gray cloak seems to absorb light rather than be illuminated by it. On command, the cloak makes its wearer ethereal (as the <i>ethereal jaunt</i> spell). The effect is dismissible. The cloak works for a total of up to 10 minutes per day. This duration need not be continuous.</p><p>Strong transmutation; CL 15th; Craft Wondrous Item, <i>ethereal jaunt</i>; Price 55,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1359,'Cloak of the Manta Ray','Wondrous',NULL,'No','Moderate transmutation','9','7,200 gp',NULL,'Craft Wondrous Item, polymorph, water breathing',NULL,'1 lb','\n      <div topic=\"Cloak of the Manta Ray\" level=\"8\"><p><b>Cloak of the Manta Ray:</b> This cloak appears to be made of leather until the wearer enters salt water. At that time the <i>cloak of the manta ray</i> adheres to the individual, and he appears nearly identical to a manta ray (as the <i>polymorph</i> spell, except that it allows only manta ray form). He gains a +3 natural armor bonus, the ability to breathe underwater, and a swim speed of 60 feet, like a real manta ray.</p><p>Although the cloak does not enable the wearer to bite opponents as a manta ray does, it does have a tail spine that can be used to strike at opponents behind the wearer, dealing 1d6 points of damage. This attack can be used in addition to any other attack the character has, using his highest melee attack bonus. The wearer can release his arms from the cloak without sacrificing underwater movement if so desired.</p><p>Moderate transmutation; CL 9th; Craft Wondrous Item, <i>polymorph</i>, <i>water breathing</i>; Price 7,200 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1360,'Cloak of Resistance +1','Wondrous',NULL,'No','Faint abjuration','5','1,000 gp',NULL,'Craft Wondrous Item, resistance, creator\'s caster level must be at least three times the cloak\'s bonus',NULL,'1 lb','\n      <div topic=\"Cloak of Resistance\" level=\"8\"><p><b>Cloak of Resistance:</b> These garments offer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will).</p><p>Faint abjuration; CL 5th; Craft Wondrous Item, <i>resistance</i>,  creator\'s caster level must be at least three times the cloak\'s bonus; Price 1,000 gp (+1), 4,000 gp (+2), 9,000 gp (+3), 16,000 gp (+4), 25,000 gp (+5); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1361,'Cloak of Resistance +2','Wondrous',NULL,'No','Faint abjuration','5','4,000 gp',NULL,'Craft Wondrous Item, resistance, creator\'s caster level must be at least three times the cloak\'s bonus',NULL,'1 lb','\n      <div topic=\"Cloak of Resistance\" level=\"8\"><p><b>Cloak of Resistance:</b> These garments offer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will).</p><p>Faint abjuration; CL 5th; Craft Wondrous Item, <i>resistance</i>,  creator\'s caster level must be at least three times the cloak\'s bonus; Price 1,000 gp (+1), 4,000 gp (+2), 9,000 gp (+3), 16,000 gp (+4), 25,000 gp (+5); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1362,'Cloak of Resistance +3','Wondrous',NULL,'No','Faint abjuration','5','9,000 gp',NULL,'Craft Wondrous Item, resistance, creator\'s caster level must be at least three times the cloak\'s bonus',NULL,'1 lb','\n      <div topic=\"Cloak of Resistance\" level=\"8\"><p><b>Cloak of Resistance:</b> These garments offer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will).</p><p>Faint abjuration; CL 5th; Craft Wondrous Item, <i>resistance</i>,  creator\'s caster level must be at least three times the cloak\'s bonus; Price 1,000 gp (+1), 4,000 gp (+2), 9,000 gp (+3), 16,000 gp (+4), 25,000 gp (+5); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1363,'Cloak of Resistance +4','Wondrous',NULL,'No','Faint abjuration','5','16,000 gp',NULL,'Craft Wondrous Item, resistance, creator\'s caster level must be at least three times the cloak\'s bonus',NULL,'1 lb','\n      <div topic=\"Cloak of Resistance\" level=\"8\"><p><b>Cloak of Resistance:</b> These garments offer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will).</p><p>Faint abjuration; CL 5th; Craft Wondrous Item, <i>resistance</i>,  creator\'s caster level must be at least three times the cloak\'s bonus; Price 1,000 gp (+1), 4,000 gp (+2), 9,000 gp (+3), 16,000 gp (+4), 25,000 gp (+5); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1364,'Cloak of Resistance +5','Wondrous',NULL,'No','Faint abjuration','5','25,000 gp',NULL,'Craft Wondrous Item, resistance, creator\'s caster level must be at least three times the cloak\'s bonus',NULL,'1 lb','\n      <div topic=\"Cloak of Resistance\" level=\"8\"><p><b>Cloak of Resistance:</b> These garments offer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will).</p><p>Faint abjuration; CL 5th; Craft Wondrous Item, <i>resistance</i>,  creator\'s caster level must be at least three times the cloak\'s bonus; Price 1,000 gp (+1), 4,000 gp (+2), 9,000 gp (+3), 16,000 gp (+4), 25,000 gp (+5); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1365,'Crystal Ball','Wondrous',NULL,'No','Moderate divination','10',NULL,NULL,'Craft Wondrous Item, scrying (plus any additional spells put into item)',NULL,'7 lb','\n      <div topic=\"Crystal Ball\" level=\"8\"><p><b>Crystal Ball:</b> This is the most common form of scrying device, a crystal sphere about 6 inches in diameter. A character can use the device to see over virtually any distance or into other planes of existence, as with the spell <i>scrying</i> (Will DC 16 negates).</p><p>Certain <i>crystal balls</i> have additional powers that can be used through the <i>Crystal ball</i> on the target viewed.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Crystal Ball Type</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Crystal ball</i><br/></td>\n<td>42,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Crystal ball</i> with <i>see invisibility</i><br/></td>\n<td>50,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Crystal ball</i> with <i>detect thoughts (Will DC 13 negates)</i><br/></td>\n<td>51,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Crystal ball</i> with <i>telepathy</i>*<br/></td>\n<td>70,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Crystal ball</i> with <i>true seeing</i><br/></td>\n<td>80,000 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">* The viewer is able to send and receive silent mental messages with the person appearing in the crystal ball. Once per day the character may attempt to implant a <i>suggestion</i> (as the spell, Will DC 14 negates) as well.<br/></td>\n\n</tr>\n</table><p>Moderate divination; CL 10th; Craft Wondrous Item, <i>scrying</i> (plus any additional spells put into item); Weight 7 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1366,'Cube of Force','Wondrous',NULL,'No','Moderate evocation','10','62,000 gp',NULL,'Craft Wondrous Item, wall of force',NULL,NULL,'\n      <div topic=\"Cube of Force\" level=\"8\"><p><b>Cube of Force:</b> This device is about 3/4 inch across and can be made of ivory, bone, or any hard mineral. It enables its possessor to put up a special <i>wall of force</i> 10 feet on a side around her person. This cubic screen moves with the character and is impervious to the attack forms mentioned on the table below. The cube has 36 charges, which are renewed each day. The possessor presses one face of the cube to activate a particular type of screen or to deactivate the device. Each effect costs a certain number of charges to maintain for every minute (or portion of a minute) it is in operation. Also, when an effect is active, the possessor\'s speed is limited to the maximum value given on the table.</p><p>When the <i>cube of force</i> is active, attacks dealing more than 30 points of damage drain 1 charge for every 10 points of damage beyond 30 that they deal. Spells that affect the integrity of the screen also drain extra charges. These spells (given in the list below) cannot be cast into or out of the cube:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Cube Face</b><br/></td> <td><b>Charge Cost per Minute</b><br/></td>\n<td><b>Maximum Speed</b><br/></td>\n<td><b>Effect</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>1<br/></td>\n<td>1<br/></td>\n<td>30 ft.<br/></td>\n<td>Keeps out gases, wind, etc.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>2<br/></td>\n<td>2<br/></td>\n<td>20 ft.<br/></td>\n<td>Keeps out nonliving matter<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>3<br/></td>\n<td>3<br/></td>\n<td>15 ft.<br/></td>\n<td>Keeps out living matter<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>4<br/></td>\n<td>4<br/></td>\n<td>10 ft.<br/></td>\n<td>Keeps out magic<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>5<br/></td>\n<td>6<br/></td>\n<td>10 ft.<br/></td>\n<td>Keeps out all things<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>6<br/></td>\n<td>0<br/></td>\n<td>As normal<br/></td>\n<td>Deactivates<br/></td>\n\n</tr>\n</table><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack Form</b><br/></td>\n<td><b>Extra Charges</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Horn of blasting</i><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Wall of fire</i><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Passwall</i><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Disintegrate</i><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Phase door</i><br/></td>\n<td>5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><i>Prismatic spray</i><br/></td>\n<td>7<br/></td>\n\n</tr>\n</table><p>Moderate evocation; CL 10th; Craft Wondrous Item, <i>wall of force</i>; Price 62,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1367,'Cube of Frost Resistance','Wondrous',NULL,'No','Faint abjuration','5','27,000 gp',NULL,'Craft Wondrous Item, protection from energy',NULL,NULL,'\n      <div topic=\"Cube of Frost Resistance\" level=\"8\"><p><b>Cube of Frost Resistance:</b> This cube is activated or deactivated by pressing one side. When activated, it creates a cube-shaped area 10 feet on a side centered on the possessor (or on the cube itself, if the item is later placed on a surface). The temperature within this area is always at least 65&#xB0;F. The field absorbs all cold-based attacks. However, if the field is subjected to more than 50 points of cold damage in 1 round (from one or multiple attacks), it collapses into its portable form and cannot be reactivated for 1 hour. If the field absorbs more than 100 points of cold damage in a 10-round period, the cube is destroyed.</p><p>Faint abjuration; CL 5th; Craft Wondrous Item, <i>protection from energy</i>; Price 27,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1368,'Cubic Gate','Wondrous',NULL,'No','Strong conjuration','13','164,000 gp',NULL,'Craft Wondrous Item, plane shift',NULL,NULL,'\n      <div topic=\"Cubic Gate\" level=\"8\"><p><b>Cubic Gate:</b> This item is fashioned from carnelian. Each of the six sides of the cube is keyed to a plane, one of which is the Material Plane. The character creating the item should choose the planes to which the other five sides are keyed.</p><p>If a side of the <i>cubic gate</i> is pressed once, it opens a <i>gate</i> to a random point on the plane keyed to that side. There is a 10% chance per minute that an outsider from that plane (determine randomly) comes through it looking for food, fun, or trouble. Pressing the side a second time closes the <i>gate</i>. It is impossible to open more than one <i>gate</i> at a time.</p><p>If a side is pressed twice in quick succession, the character so doing is transported to a random point on the other plane, along with all creatures in adjacent squares. (The other creatures may avoid this fate by succeeding on DC 23 Will saves).</p><p>Strong conjuration; CL 13th; Craft Wondrous Item, <i>plane shift</i>; Price 164,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1369,'Darkskull','Wondrous',NULL,'No','Moderate evocation [evil]','9','60,000 gp',NULL,'Craft Wondrous Item, unhallow, creator must be evil',NULL,'5 lb','\n      <div topic=\"Darkskull\" level=\"8\"><p><b>Darkskull:</b> This skull, carved from ebony, is wholly evil. Wherever the skull goes, the area around it is treated as though an <i>unhallow</i> spell had been cast with the skull as the touched point of origin (except that no additional spell effect is tied or fixed to the <i>Darkskull</i>).</p><p>Moderate evocation [evil]; CL 9th; Craft Wondrous Item, <i>unhallow</i>,  creator must be evil; Price 60,000 gp; Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1370,'Decanter of Endless Water','Wondrous',NULL,'No','Moderate transmutation','9','9,000 gp',NULL,'Craft Wondrous Item, control water',NULL,'2 lb','\n      <div topic=\"Decanter of Endless Water\" level=\"8\"><p><b>Decanter of Endless Water:</b> If the stopper is removed from this ordinary-looking flask and a command word spoken, an amount of fresh or salt water pours out. Separate command words determine the type as well as the volume and velocity.</p><ul>\n <li> \'Stream\' pours out 1 gallon per round.</li>\n <li> \'Fountain\' produces a 5-foot-long stream at 5 gallons per round.</li>\n <li> \'Geyser\' produces a 20-foot-long, 1-foot-wide stream at 30 gallons per round.</li>\n</ul><p>The geyser effect causes considerable back pressure, requiring the holder to make a DC 12 Strength check to avoid being knocked down. The force of the geyser deals 1d4 points of damage but can only affect one target per round. The command word must be spoken to stop it.</p><p>Moderate transmutation; CL 9th; Craft Wondrous Item, <i>control water</i>; Price 9,000 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1371,'Deck of Illusions','Wondrous',NULL,'No','Faint illusion','6','8,100 gp',NULL,'Craft Wondrous Item, major image',NULL,'1/2 lb','\n      <div topic=\"Deck of Illusions\" level=\"8\"><p><b>Deck of Illusions:</b> This set of parchment cards is usually found in an ivory, leather, or wooden box. A full deck consists of thirty-four cards. When a card is drawn at random and thrown to the ground, a <i>major image</i> of a creature is formed. The figment lasts until dispelled. The illusory creature cannot move more than 30 feet away from where the card landed, but otherwise moves and acts as if it were real. At all times it obeys the desires of the character who drew the card. When the illusion is dispelled, the card becomes blank and cannot be used again. If the card is picked up, the illusion is automatically and instantly dispelled. The cards in a deck and the illusions they bring forth are summarized on the following table. (Use one of the first two columns to simulate the contents of a full deck using either ordinary playing cards or tarot cards.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Playing Card</b><br/></td>\n<td><b>Tarot Card</b><br/></td>\n<td><b>Creature</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ace of hearts<br/></td>\n<td>IV. The Emperor<br/></td>\n<td>Red dragon<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>King of hearts<br/></td>\n<td>Knight of swords<br/></td>\n<td>Male human fighter and four guards<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Queen of hearts<br/></td>\n<td>Queen of staves<br/></td>\n<td>Female human wizard<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Jack of hearts<br/></td>\n<td>King of staves<br/></td>\n<td>Male human druid<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ten of hearts<br/></td>\n<td>VII. The Chariot<br/></td>\n<td>Cloud giant<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Nine of hearts<br/></td>\n<td>Page of staves<br/></td>\n<td>Ettin<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Eight of hearts<br/></td>\n<td>Ace of cups<br/></td>\n<td>Bugbear<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Two of hearts<br/></td>\n<td>Five of staves<br/></td>\n<td>Goblin<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Playing Card</b><br/></td>\n<td><b>Tarot Card</b><br/></td>\n<td><b>Creature</b><br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ace of diamonds<br/></td>\n<td>III. The Empress<br/></td>\n<td>Glabrezu (demon)<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>King of diamonds<br/></td>\n<td>Two of cups<br/></td>\n<td>Male elf wizard and female apprentice<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Queen of diamonds<br/></td>\n<td>Queen of swords<br/></td>\n<td>Half-elf ranger (female)<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Jack of diamonds<br/></td>\n<td>XIV. Temperance<br/></td>\n<td>Harpy<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ten of diamonds<br/></td>\n<td>Seven of staves<br/></td>\n<td>Male half-orc barbarian<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Nine of diamonds<br/></td>\n<td>Four of pentacles<br/></td>\n<td>Ogre mage<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Eight of diamonds<br/></td>\n<td>Ace of pentacles<br/></td>\n<td>Gnoll<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Two of diamonds<br/></td>\n<td>Six of pentacles<br/></td>\n<td>Kobold<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Playing Card</b><br/></td>\n<td><b>Tarot Card</b><br/></td>\n<td><b>Creature</b><br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ace of spades<br/></td>\n<td>II. The High Priestess<br/></td>\n<td>Lich<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>King of spades<br/></td>\n<td>Three of staves<br/></td>\n<td>Three male human clerics<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Queen of spades<br/></td>\n<td>Four of cups<br/></td>\n<td>Medusa<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Jack of spades<br/></td>\n<td>Knight of pentacles<br/></td>\n<td>Male dwarf paladin<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ten of spades<br/></td>\n<td>Seven of swords<br/></td>\n<td>Frost giant<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Nine of spades<br/></td>\n<td>Three of swords<br/></td>\n<td>Troll<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Eight of spades<br/></td>\n<td>Ace of swords<br/></td>\n<td>Hobgoblin<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Two of spades<br/></td>\n<td>Five of cups<br/></td>\n<td>Goblin<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Playing Card</b><br/></td>\n<td><b>Tarot Card</b><br/></td>\n<td><b>Creature</b><br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ace of clubs<br/></td>\n<td>VIII. Strength<br/></td>\n<td>Iron golem<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>King of clubs<br/></td>\n<td>Page of pentacles<br/></td>\n<td>Three male halfling rogues<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Queen of clubs<br/></td>\n<td>Ten of cups<br/></td>\n<td>Pixies<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Jack of clubs<br/></td>\n<td>Nine of pentacles<br/></td>\n<td>Female half-elf bard<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ten of clubs<br/></td>\n<td>Nine of staves<br/></td>\n<td>Hill giant<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Nine of clubs<br/></td>\n<td>King of swords<br/></td>\n<td>Ogre<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Eight of clubs<br/></td>\n<td>Ace of staves<br/></td>\n<td>Orc<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Two of clubs<br/></td>\n<td>Five of cups<br/></td>\n<td>Kobold<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Playing Card</b><br/></td>\n<td><b>Tarot Card</b><br/></td>\n<td><b>Creature</b><br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Joker<br/></td>\n<td>Two of pentacles<br/></td>\n<td>Illusion of deck\'s owner<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Joker<br/></td>\n<td>Two of staves<br/></td>\n<td>Illusion of deck\'s owner (sex reversed)<br/></td>\n\n</tr>\n</table><p>A randomly generated deck is usually complete (11-100 on d%), but may be discovered (01-10) with 1d20 of its cards missing. If cards are missing, reduce the price by a corresponding amount.</p><p>Faint illusion; CL 6th; Craft Wondrous Item, <i>major image</i>; Price 8,100 gp; Weight 1/2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1372,'Dimensional Shackles','Wondrous',NULL,'No','Moderate abjuration','11','28,000 gp',NULL,'Craft Wondrous Item, dimensional anchor',NULL,'5 lb','\n      <div topic=\"Dimensional Shackles\" level=\"8\"><p><b>Dimensional Shackles:</b> These shackles have golden runes traced across their cold iron surface. Any creature bound within them is affected as if a <i>dimensional anchor</i> spell were cast upon her (no save). They fit any Small to Large creature. The DC to break or slip out of the shackles is 30.</p><p>Moderate abjuration; CL 11th; Craft Wondrous Item, <i>dimensional anchor</i>; Price 28,000 gp; Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1373,'Drums of Panic','Wondrous',NULL,'No','Moderate necromancy','7','30,000 gp',NULL,'Craft Wondrous Item, fear',NULL,'10 lb. for the pair','\n      <div topic=\"Drums of Panic\" level=\"8\"><p><b>Drums of Panic:</b> These drums are kettle drums (hemispheres about 1-1/2 feet in diameter on stands). They come in pairs and are unremarkable in appearance. If both of the pair are sounded, all creatures within 120 feet (with the exception of those within a 20-foot-radius safe zone around the drums) are affected as by a <i>fear</i> spell (Will DC 16 partial). <i>Drums of panic</i> can be used once per day.</p><p>Moderate necromancy; CL 7th; Craft Wondrous Item, <i>fear</i>; Price 30,000 gp; Weight 10 lb. for the pair.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1374,'Dust of Appearance','Wondrous',NULL,'No','Faint conjuration','5','1,800 gp',NULL,'Craft Wondrous Item, glitterdust',NULL,NULL,'\n      <div topic=\"Dust of Appearance\" level=\"8\"><p><b>Dust of Appearance:</b> This fine powder appears to be a very fine, very light metallic dust. A single handful of this substance flung into the air coats objects within a 10-foot radius, making them visible even if they are invisible. It likewise negates the effects of <i>blur</i> and <i>displacement</i>. (In this, it works just like the <i>faerie fire</i> spell). The dust also reveals figments, <i>mirror images</i>, and <i>projected images</i> for what they are. A creature coated with the dust takes a -30 penalty on its Hide checks. The dust\'s effect lasts for 5 minutes.</p><p><i>Dust of appearance</i> is typically stored in small silk packets or hollow bone tubes.</p><p>Faint conjuration; CL 5th; Craft Wondrous Item, <i>glitterdust</i>; Price 1,800 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1375,'Dust of Disappearance','Wondrous',NULL,'No','Moderate illusion','7','3,500 gp',NULL,'Craft Wondrous Item, greater invisibility',NULL,NULL,'\n      <div topic=\"Dust of Disappearance\" level=\"8\"><p><b>Dust of Disappearance:</b> This dust looks just like <i>Dust of appearance</i> and is typically stored in the same manner. A creature or object touched by it becomes invisible (as <i>greater invisibility</i>). Normal vision can\'t see dusted creatures or objects, nor can they be detected by magical means, including <i>see invisibility</i> or <i>invisibility purge</i>. <i>Dust of appearance</i>,  however, does reveal people and objects made invisible by <i>dust of disappearance</i>. Other factors, such as sound and smell, also allow possible detection.</p><p>The <i>greater invisibility</i> bestowed by the dust lasts for 2d6 rounds. The invisible creature doesn\'t know when the duration will end.</p><p>Moderate illusion; CL 7th; Craft Wondrous Item, <i>greater invisibility</i>; Price 3,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1376,'Dust of Dryness','Wondrous',NULL,'No','Moderate transmutation','11','850 gp',NULL,'Craft Wondrous Item, control water',NULL,NULL,'\n      <div topic=\"Dust of Dryness\" level=\"8\"><p><b>Dust of Dryness:</b> This special dust has many uses. If it is thrown into water, a volume of as much as 100 gallons is instantly transformed to nothingness, and the dust becomes a marble-sized pellet, floating or resting where it was thrown. If this pellet is hurled down, it breaks and releases the same volume of water. The dust affects only water (fresh, salt, alkaline), not other liquids.</p><p>If the dust is employed against an elemental with the water subtype, the creature must make a DC 18 Fortitude save or be destroyed. The dust deals 5d6 points of damage to the creature even if its saving throw succeeds.</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>control water</i>; Price 850 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1377,'Dust of Illusion','Wondrous',NULL,'No','Faint illusion','6','1,200 gp',NULL,'Craft Wondrous Item, disguise self',NULL,NULL,'\n      <div topic=\"Dust of Illusion\" level=\"8\"><p><b>Dust of Illusion:</b> This unremarkable powder resembles chalk dust or powdered graphite. Stare at it, however, and the dust changes color and form. Put <i>dust of illusion</i> on a creature, and that creature is affected as if by a <i>disguise self</i> glamer, with the individual who sprinkles the dust envisioning the illusion desired. An unwilling target is allowed a DC 11 Reflex save to avoid the dust. The glamer lasts for 2 hours.</p><p>Faint illusion; CL 6th; Craft Wondrous Item, <i>disguise self</i>; Price 1,200 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1378,'Dust of Tracelessness','Wondrous',NULL,'No','Faint transmutation','3','250 gp',NULL,'Craft Wondrous Item, pass without trace',NULL,NULL,'\n      <div topic=\"Dust of Tracelessness\" level=\"8\"><p><b>Dust of Tracelessness:</b> This normal-seeming dust is actually a magic powder that can conceal the passage of its possessor and his companions. Tossing a handful of this dust into the air causes a chamber of up to 100 square feet of floor space to become as dusty, dirty, and cobweb-laden as if it had been abandoned and disused for a decade.</p><p>A handful of dust sprinkled along a trail causes evidence of the passage of as many as a dozen men and horses to be obliterated for 250 feet back into the distance. The results of the dust are instantaneous, and no magical aura lingers afterward from this use of the dust. Survival checks made to track a quarry across an area affected by this dust have a DC 20 higher than normal.</p><p>Faint transmutation; CL 3rd; Craft Wondrous Item, <i>pass without trace</i>; Price 250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1379,'Efficient Quiver','Wondrous',NULL,'No','Moderate conjuration','9','1,800 gp',NULL,'Craft Wondrous Item, secret chest',NULL,'2 lb','\n      <div topic=\"Efficient Quiver\" level=\"8\"><p><b>Efficient Quiver:</b> This appears to be a typical arrow container capable of holding about twenty arrows. It has three distinct portions, each with a nondimensional space allowing it to store far more than would normally be possible. The first and smallest one can contain up to sixty objects of the same general size and shape as an arrow. The second slightly longer compartment holds up to eighteen objects of the same general size and shape as a javelin. The third and longest portion of the case contains as many as six objects of the same general size and shape as a bow (spears, staffs, or the like). Once the owner has filled it, the quiver can produce any item she wishes, as if from a regular quiver or scabbard. The <i>efficient</i> <i>quiver</i> weighs the same no matter what\'s placed inside it.</p><p>Moderate conjuration; CL 9th; Craft Wondrous Item, <i>secret chest</i>; Price 1,800 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1380,'Efreeti Bottle','Wondrous',NULL,'No','Strong conjuration','14','145,000 gp',NULL,'Craft Wondrous Item, summon monster VII',NULL,'1 lb','\n      <div topic=\"Efreeti Bottle\" level=\"8\"><p><b>Efreeti Bottle:</b> This item is typically fashioned of brass or bronze, with a lead stopper bearing special seals. A thin stream of smoke is often seen issuing from it. The bottle can be opened once per day. When opened, the efreeti imprisoned within issues from the bottle instantly. There is a 10% chance (01-10 on d%) that the efreeti is insane and attacks immediately upon being released. There is also a 10% chance (91-100) that the efreeti of the bottle grants three <i>wishes</i>. In either case, the efreeti afterward disappears forever. The other 80% of the time (11-90), the inhabitant of the bottle loyally serves the character for up to 10 minutes per day (or until the efreeti\'s death), doing as she commands. Roll each day the bottle is opened for that day\'s effect.</p><p>Strong conjuration; CL 14th; Craft Wondrous Item, <i>summon monster VII</i>; Price 145,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1381,'Elemental Gem','Wondrous',NULL,'No','Moderate conjuration','11','2,250 gp',NULL,'Craft Wondrous Item, summon nature\'s ally V',NULL,NULL,'\n      <div topic=\"Elemental Gem\" level=\"8\"><p><b>Elemental Gem:</b> This gem contains a conjuration spell attuned to a specific Elemental Plane (Air, Earth, Fire, or Water).</p><p>When the gem is crushed, smashed, or broken (a standard action), a Large elemental appears as if summoned by a <i>summon nature\'s ally</i> spell. The elemental is under the control of the creature that broke the gem.</p><p>The coloration of the gem varies with the type of elemental it summons. <i>Air elemental gems</i> are transparent, <i>earth elemental gems</i> are light brown, <i>fire elemental gems</i> are reddish orange, and <i>water elemental gems</i> are blue-green.</p><p>Moderate conjuration; CL 11th; Craft Wondrous Item, <i>summon nature\'s ally V</i>; Price 2,250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1382,'Elixir of Fire Breath','Wondrous',NULL,'No','Moderate evocation','11','1,100 gp',NULL,'Craft Wondrous Item, scorching ray',NULL,NULL,'\n      <div topic=\"Elixir of Fire Breath\" level=\"8\"><p><b>Elixir of Fire Breath:</b> This strange elixir bestows upon the drinker the ability to spit gouts of flame. He can breathe fire up to three times, each time dealing 4d6 points of fire damage to a single target up to 25 feet away. The victim can attempt a DC 13 Reflex save for half damage. Unused blasts dissipate 1 hour after the liquid is consumed.</p><p>Moderate evocation; CL 11th; Craft Wondrous Item, <i>scorching ray</i>; Price 1,100 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1383,'Elixir of Hiding','Wondrous',NULL,'No','Faint illusion','5','250 gp',NULL,'Craft Wondrous Item, invisibility',NULL,NULL,'\n      <div topic=\"Elixir of Hiding\" level=\"8\"><p><b>Elixir of Hiding:</b> A character drinking this liquid gains an intuitive ability to hide (+10 competence bonus on Hide checks for 1 hour).</p><p>Faint illusion; CL 5th; Craft Wondrous Item, <i>invisibility</i>; Price 250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1384,'Elixir of Love','Wondrous',NULL,'No','Faint transmutation','4','150 gp',NULL,'Craft Wondrous Item, charm person',NULL,NULL,'\n      <div topic=\"Elixir of Love\" level=\"8\"><p><b>Elixir of Love:</b> This sweet-tasting liquid causes the character drinking it to become <i>charmed</i> with the first creature she sees after consuming the draft (as <i>charm person</i>-the drinker must be a humanoid of Medium or smaller size, Will DC 14 negates). The <i>charm</i> effects wear off in 1d3 hours.</p><p>Faint transmutation; CL 4th; Craft Wondrous Item, <i>charm person</i>; Price 150 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1385,'Elixir of Sneaking','Wondrous',NULL,'No','Faint illusion','5','250 gp',NULL,'Craft Wondrous Item, silence',NULL,NULL,'\n      <div topic=\"Elixir of Sneaking\" level=\"8\"><p><b>Elixir of Sneaking:</b> This draught of liquid grants the drinker the ability to walk softly and dampens sound around her slightly, granting a +10 competence bonus on Move Silently checks for 1 hour.</p><p>Faint illusion; CL 5th; Craft Wondrous Item, <i>silence</i>; Price 250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1386,'Elixir of Swimming','Wondrous',NULL,'No','Faint illusion','2','250 gp',NULL,'Craft Wondrous Item, creator must have 5 ranks in the Swim skill',NULL,NULL,'\n      <div topic=\"Elixir of Swimming\" level=\"8\"><p><b>Elixir of Swimming:</b> This elixir bestows swimming ability. An almost imperceptible magic sheath surrounds the drinker, allowing him to glide through the water easily (+10 competence bonus on Swim checks for 1 hour).</p><p>Faint illusion; CL 2nd; Craft Wondrous Item, creator must have 5 ranks in the Swim skill; Price 250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1387,'Elixir of Truth','Wondrous',NULL,'No','Faint enchantment','5','500 gp',NULL,'Craft Wondrous Item, zone of truth',NULL,NULL,'\n      <div topic=\"Elixir of Truth\" level=\"8\"><p><b>Elixir of Truth:</b> This elixir forces the individual drinking it to say nothing but the truth for 10 minutes (Will DC 13 negates).</p><p>She is compelled to answer any questions put to her in that time, but with each question she is free to make a separate DC 13 Will save. If one of these secondary saves is successful, she doesn\'t break free of the truth-compelling enchantment but also doesn\'t have to answer that particular question. No more than one question can be asked each round. This is a mind-affecting compulsion enchantment.</p><p>Faint enchantment; CL 5th; Craft Wondrous Item, <i>zone of truth</i>; Price 500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1388,'Elixir of Vision','Wondrous',NULL,'No','Faint divination','2','250 gp',NULL,'Craft Wondrous Item, true seeing',NULL,NULL,'\n      <div topic=\"Elixir of Vision\" level=\"8\"><p><b>Elixir of Vision:</b> Drinking this elixir grants the imbiber the ability to notice acute details with great accuracy (+10 competence bonus on Search checks for 1 hour).</p><p>Faint divination; CL 2nd; Craft Wondrous Item, <i>true seeing</i>; Price 250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1389,'Eversmoking Bottle','Wondrous',NULL,'No','Faint transmutation','3','5,400 gp',NULL,'Craft Wondrous Item, pyrotechnics',NULL,'1 lb','\n      <div topic=\"Eversmoking Bottle\" level=\"8\"><p><b>Eversmoking Bottle:</b> This metal urn is identical in appearance to an <i>Efreeti bottle</i>,  except that it does nothing but smoke. The amount of smoke is great if the stopper is pulled out, pouring from the bottle and totally obscuring vision across a 50-foot spread in 1 round. If the bottle is left unstoppered, the smoke billows out another 10 feet per round until it has covered a 100-foot radius. This area remains smoke-filled until the <i>eversmoking bottle</i> is stoppered.</p><p>The bottle must be resealed by a command word, after which the smoke dissipates normally. A moderate wind (11+ mph) disperses the smoke in 4 rounds; a strong wind (21+ mph) disperses the smoke in 1 round.</p><p>Faint transmutation; CL 3rd; Craft Wondrous Item, <i>pyrotechnics</i>; Price 5,400 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1390,'Eyes of Charming','Wondrous',NULL,'No','Moderate enchantment','7','56,000 gp for a pair',NULL,'Craft Wondrous Item, Heighten Spell, charm person',NULL,NULL,'\n      <div topic=\"Eyes of Charming\" level=\"8\"><p><b>Eyes of Charming:</b> These two crystal lenses fit over the user\'s eyes. The wearer is able to use <i>charm person</i> (one target per round) merely by meeting a target\'s gaze. Those failing a DC 16 Will save are <i>charmed</i> as per the spell. If the wearer has only one lens, the DC of the saving throw is reduced to 10.</p><p>Moderate enchantment; CL 7th; Craft Wondrous Item, Heighten Spell, <i>charm person</i>; Price 56,000 gp for a pair.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1391,'Eyes of Doom','Wondrous',NULL,'No','Moderate necromancy','11','25,000 gp',NULL,'Craft Wondrous Item, doom, deathwatch, fear',NULL,NULL,'\n      <div topic=\"Eyes of Doom\" level=\"8\"><p><b>Eyes of Doom:</b> These crystal lenses fit over the user\'s eyes, enabling him to cast <i>doom</i> upon those around him (one target per round) as a gaze attack, except that the wearer must take a standard action, and those merely looking at the wearer are not affected. Those failing a DC 11 Will save are affected as by the <i>doom</i> spell. If the wearer has only one lens, the DC of the saving throw is reduced to 10. However, if the wearer has both lenses, he gains the additional power of a continual <i>deathwatch</i> effect and can use <i>fear</i> (Will DC 16 partial) as a normal gaze attack once per week.</p><p>Moderate necromancy; CL 11th; Craft Wondrous Item, <i>doom</i>,  <i>deathwatch</i>,  <i>fear</i>; Price 25,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1392,'Eyes of the Eagle','Wondrous',NULL,'No','Faint divination','3','2,500 gp',NULL,'Craft Wondrous Item, clairaudience/clairvoyance',NULL,NULL,'\n      <div topic=\"Eyes of the Eagle\" level=\"8\"><p><b>Eyes of the Eagle:</b> These items are made of special crystal and fit over the eyes of the wearer. These lenses grant a +5 competence bonus on Spot checks. Wearing only one of the pair causes a character to become dizzy and, in effect, stunned for 1 round. Thereafter, the wearer can use the single lens without being stunned so long as she covers her other eye. Of course, she can remove the single lens and see normally at any time, or wear both lenses to end or avoid the dizziness.</p><p>Faint divination; CL 3rd; Craft Wondrous Item, <i>clairaudience/clairvoyance</i>; Price 2,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1393,'Eyes of Petrification','Wondrous',NULL,'No','Moderate transmutation','11','98,000 gp',NULL,'Craft Wondrous Item, flesh to stone',NULL,NULL,'\n      <div topic=\"Eyes of Petrification\" level=\"8\"><p><b>Eyes of Petrification:</b> These items are made of special crystal and fit over the eyes of the wearer. They allow her to use a petrification gaze attack (Fortitude DC 19 negates) for 10 rounds per day. Both lenses must be worn for the magic to be effective.</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>flesh to stone</i>; Price 98,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1394,'Figurines of Wondrous Power','Wondrous',NULL,'No','Faint enchantment and transmutation','6','3,800 gp',NULL,'Craft Wondrous Item, animal messenger, animate objects',NULL,NULL,'\n      <div topic=\"Figurines of Wondrous Power\" level=\"8\"><p><b>Figurines of Wondrous Power:</b> Each of the several kinds of <i>figurines of wondrous power</i> appears to be a miniature statuette of a creature an inch or so high (with one exception). When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size (except when noted otherwise below). The creature obeys and serves its owner. Unless stated otherwise, the creature understands Common but does not speak.</p><p>If a <i>figurine of wondrous power</i> is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time.</p><p><i>Bronze Griffon:</i> When animated, a <i>bronze griffon</i> acts in all ways like a normal griffon under the command of its possessor. The item can be used twice per week for up to 6 hours per use. When 6 hours have passed or when the command word is spoken, the <i>bronze griffon</i> once again becomes a tiny statuette.</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>animate objects</i>; Price 10,000 gp.</p><p><i>Ebony Fly:</i> When animated, an <i>ebony fly</i> is the size of a pony and has all the statistics of a hippogriff but can make no attacks. The item can be used three times per week for up to 12 hours per use. When 12 hours have passed or when the command word is spoken, the <i>ebony fly</i> again becomes a tiny statuette.</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>animate objects</i>; Price 10,000 gp.</p><p><i>Golden Lions:</i> These figurines come in pairs. They become normal adult male lions. If slain in combat, the lions cannot be brought back from statuette form for one full week. Otherwise, they can be used once per day for up to 1 hour. They enlarge and shrink upon speaking the command word.</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>animate objects</i>; Price 16,500 gp.</p><p><i>Ivory Goats:</i> These figurines come in threes. Each goat of this trio looks slightly different from the others, and each has a different function:</p><ul>\n <li> <i>The Goat of Traveling:</i> This statuette provides a speedy and enduring mount equal to that of a heavy horse in every way except appearance. The goat can travel for a maximum of one day each week-continuously or in any combination of periods totaling 24 hours. At this point, or when the command word is uttered, it returns to its statuette form for not less than one day before it can again be used.</li>\n <li> <i>The Goat of Travail:</i> This statuette becomes an enormous creature, larger than a bull, with the statistics of a nightmare except for the addition of a pair of wicked horns of exceptional size (damage 1d8+4 for each horn). If it is charging to attack, it may only use its horns (but add 6 points of damage to each successful attack in that round). It can be called to life just once per month for up to 12 hours at a time.</li>\n <li> <i>The Goat of Terror:</i> When called upon with the proper command word, this statuette becomes a destrier-like mount, with the statistics of a light warhorse. However, its rider can employ the goat\'s horns as weapons (one horn as a <i>+3 heavy lance</i>,  the other as a <i>+5 longsword</i>). When ridden in an attack against an opponent, the <i>goat of terror</i> radiates <i>fear</i> as the spell in a 30-foot radius (Will DC 16 partial). It can be used once every two weeks for up to 3 hours per use.</li>\n</ul><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>animate objects</i>; Price 21,000 gp.</p><p><i>Marble Elephant:</i> This is the largest of the figurines, the statuette being about the size of a human hand. Upon utterance of the command word, a <i>marble elephant</i> grows to the size and specifications of a true elephant. The animal created from the statuette is fully obedient to the figurine\'s owner, serving as a beast of burden, a mount, or a combatant. The statuette can be used four times per month for up to 24 hours at a time.</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>animate objects</i>; Price 17,000 gp.</p><p><i>Obsidian Steed:</i> This figurine appears to be a small, shapeless lump of black stone. Only careful inspection reveals that it vaguely resembles some form of quadruped. On command, the near-formless piece of obsidian becomes a fantastic mount. Treat it as a heavy warhorse with the following additional powers usable once per round at will: <i>overland flight</i>,  <i>plane shift</i>,  and <i>ethereal jaunt</i>. The steed allows itself to be ridden, but if the rider is of good alignment, the steed is 10% likely per use to carry him to the lower planes and then return to its statuette form. The statuette can be used once per week for one continuous period of up to 24 hours. Note that when an <i>obsidian steed</i> becomes ethereal or <i>plane shifts</i>,  its rider and his gear follow suit.</p><p>Thus, the user can travel to other planes via this means.</p><p>Strong conjuration and transmutation; CL 15th; Craft Wondrous Item, <i>animate objects</i>,  <i>etherealness</i>,  <i>fly</i>,  <i>plane shift</i>; Price 28,500 gp.</p><p><i>Onyx Dog:</i> When commanded, this statuette changes into a creature with the same properties as a riding dog except that it is endowed with an Intelligence of 8, can communicate in Common, and has exceptional olfactory and visual abilities. (It has the scent ability and adds +4 to its Spot and Search checks.) It has 60-foot darkvision, and it can <i>see invisibility</i>. An <i>onyx dog</i> can be used once per week for up to 6 hours. It obeys only its owner.</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>animate objects</i>; Price 15,500 gp.</p><p><i>Serpentine Owl:</i> This figurine becomes either a normal-sized horned owl or a giant owl according to the command word used. The transformation can take place once per day, with a maximum duration of 8 continuous hours. However, after three transformations into giant owl form, the statuette loses all its magical properties. The owl communicates with its owner by telepathic means, informing her of all it sees and hears. (Remember the limitations of its Intelligence.)</p><p>Moderate transmutation; CL 11th; Craft Wondrous Item, <i>animate objects</i>; Price 9,100 gp.</p><p><i>Silver Raven:</i> This silver figurine turns into a raven on command (but it retains its metallic consistency, which gives it hardness 10). Another command sends it off into the air, bearing a message just like a creature affected by an <i>animal messenger</i> spell. If not commanded to carry a message, the raven obeys the commands of its owner, although it has no special powers or telepathic abilities. It can maintain its nonfigurine status for only 24 hours per week, but the duration need not be continuous.</p><p>Faint enchantment and transmutation; CL 6th; Craft Wondrous Item, <i>animal messenger</i>,  <i>animate objects</i>; Price 3,800 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1395,'Feather Token, Anchor','Wondrous',NULL,'No','Moderate conjuration','12','50 gp',NULL,'Craft Wondrous Item, major creation',NULL,NULL,'\n      <div topic=\"Feather Token\" level=\"8\"><p><b>Feather Token:</b> Each of these items is a small feather that has a power to suit a special need. The kinds of tokens are described below. Each token is usable once.</p><p><i>Anchor:</i> A token useful to moor a craft in water so as to render it immobile for up to one day.</p><p><i>Bird:</i> A token that can be used to deliver a small written message unerringly to a designated target as would a carrier pigeon. The token lasts as long as it takes to carry the message.</p><p><i>Fan:</i> A token that forms a huge flapping fan, causing a breeze of sufficient strength to propel one ship (about 25 mph). This wind is not cumulative with existing wind speed. The token can, however, be used to lessen existing winds, creating an area of relative calm or lighter winds (but wave size in a storm is not affected). The fan can be used for up to 8 hours. It does not function on land.</p><p><i>Swan Boat:</i> A token that forms a swanlike boat capable of moving on water at a speed of 60 feet. It can carry eight horses and gear or thirty-two Medium characters or any equivalent combination. The boat lasts for one day.</p><p><i>Tree:</i> A token that causes a great oak to spring into being (5-foot diameter trunk, 60-foot height, 40-foot top diameter). This is an instantaneous effect.</p><p><i>Whip:</i> A token that forms into a huge leather whip and wields itself against any opponent desired just like a dancing weapon. The weapon has a +10 base attack bonus, does 1d6+1 points of damage, has a +1 enhancement bonus on attack and damage rolls, and a makes a free grapple attack (with a +15 attack bonus) if it hits. The whip lasts no longer than 1 hour.</p><p>Moderate conjuration; CL 12th; Craft Wondrous Item, <i>major creation</i>; Price 50 gp (<i>anchor</i>), 300 gp (<i>bird</i>), 200 gp (<i>fan</i>), 450 gp (<i>swan boat</i>), 400 gp (<i>tree</i>), 500 gp (<i>whip</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1396,'Feather Token, Bird','Wondrous',NULL,'No','Moderate conjuration','12','300 gp',NULL,'Craft Wondrous Item, major creation',NULL,NULL,'\n      <div topic=\"Feather Token\" level=\"8\"><p><b>Feather Token:</b> Each of these items is a small feather that has a power to suit a special need. The kinds of tokens are described below. Each token is usable once.</p><p><i>Anchor:</i> A token useful to moor a craft in water so as to render it immobile for up to one day.</p><p><i>Bird:</i> A token that can be used to deliver a small written message unerringly to a designated target as would a carrier pigeon. The token lasts as long as it takes to carry the message.</p><p><i>Fan:</i> A token that forms a huge flapping fan, causing a breeze of sufficient strength to propel one ship (about 25 mph). This wind is not cumulative with existing wind speed. The token can, however, be used to lessen existing winds, creating an area of relative calm or lighter winds (but wave size in a storm is not affected). The fan can be used for up to 8 hours. It does not function on land.</p><p><i>Swan Boat:</i> A token that forms a swanlike boat capable of moving on water at a speed of 60 feet. It can carry eight horses and gear or thirty-two Medium characters or any equivalent combination. The boat lasts for one day.</p><p><i>Tree:</i> A token that causes a great oak to spring into being (5-foot diameter trunk, 60-foot height, 40-foot top diameter). This is an instantaneous effect.</p><p><i>Whip:</i> A token that forms into a huge leather whip and wields itself against any opponent desired just like a dancing weapon. The weapon has a +10 base attack bonus, does 1d6+1 points of damage, has a +1 enhancement bonus on attack and damage rolls, and a makes a free grapple attack (with a +15 attack bonus) if it hits. The whip lasts no longer than 1 hour.</p><p>Moderate conjuration; CL 12th; Craft Wondrous Item, <i>major creation</i>; Price 50 gp (<i>anchor</i>), 300 gp (<i>bird</i>), 200 gp (<i>fan</i>), 450 gp (<i>swan boat</i>), 400 gp (<i>tree</i>), 500 gp (<i>whip</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1397,'Feather Token, Fan','Wondrous',NULL,'No','Moderate conjuration','12','200 gp',NULL,'Craft Wondrous Item, major creation',NULL,NULL,'\n      <div topic=\"Feather Token\" level=\"8\"><p><b>Feather Token:</b> Each of these items is a small feather that has a power to suit a special need. The kinds of tokens are described below. Each token is usable once.</p><p><i>Anchor:</i> A token useful to moor a craft in water so as to render it immobile for up to one day.</p><p><i>Bird:</i> A token that can be used to deliver a small written message unerringly to a designated target as would a carrier pigeon. The token lasts as long as it takes to carry the message.</p><p><i>Fan:</i> A token that forms a huge flapping fan, causing a breeze of sufficient strength to propel one ship (about 25 mph). This wind is not cumulative with existing wind speed. The token can, however, be used to lessen existing winds, creating an area of relative calm or lighter winds (but wave size in a storm is not affected). The fan can be used for up to 8 hours. It does not function on land.</p><p><i>Swan Boat:</i> A token that forms a swanlike boat capable of moving on water at a speed of 60 feet. It can carry eight horses and gear or thirty-two Medium characters or any equivalent combination. The boat lasts for one day.</p><p><i>Tree:</i> A token that causes a great oak to spring into being (5-foot diameter trunk, 60-foot height, 40-foot top diameter). This is an instantaneous effect.</p><p><i>Whip:</i> A token that forms into a huge leather whip and wields itself against any opponent desired just like a dancing weapon. The weapon has a +10 base attack bonus, does 1d6+1 points of damage, has a +1 enhancement bonus on attack and damage rolls, and a makes a free grapple attack (with a +15 attack bonus) if it hits. The whip lasts no longer than 1 hour.</p><p>Moderate conjuration; CL 12th; Craft Wondrous Item, <i>major creation</i>; Price 50 gp (<i>anchor</i>), 300 gp (<i>bird</i>), 200 gp (<i>fan</i>), 450 gp (<i>swan boat</i>), 400 gp (<i>tree</i>), 500 gp (<i>whip</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
